%% APF local obstacle avoidance visualization from exported ROS bag CSV files
% Expected files generated by export_apf_bag_to_csv.py:
%   strategic_goal_path.csv
%   predicted_target_trajectory.csv
%   estimated_object_state.csv
%   end_effector_path.csv
%   obstacles.csv (optional)

clear; clc;

scriptDir = fileparts(mfilename('fullpath'));
candidateDirs = {
    fullfile(scriptDir, '..', '..', '..', 'apf_local_avoidance_csv')
    fullfile(pwd, 'apf_local_avoidance_csv')
    pwd
};

dataDir = '';
for i = 1:numel(candidateDirs)
    if isfolder(candidateDirs{i}) && isfile(fullfile(candidateDirs{i}, 'strategic_goal_path.csv'))
        dataDir = candidateDirs{i};
        break;
    end
end

if isempty(dataDir)
    dataDir = uigetdir(pwd, 'Select folder containing APF local avoidance CSV files');
    if isequal(dataDir, 0)
        error('No CSV folder selected.');
    end
end

fprintf('Reading APF local avoidance CSV files from:\n  %s\n', dataDir);

apfPath = readOptionalTable(fullfile(dataDir, 'strategic_goal_path.csv'));
targetState = readOptionalTable(fullfile(dataDir, 'estimated_object_state.csv'));
targetPrediction = readOptionalTable(fullfile(dataDir, 'predicted_target_trajectory.csv'));
eePath = readOptionalTable(fullfile(dataDir, 'end_effector_path.csv'));
obstacles = readOptionalTable(fullfile(dataDir, 'obstacles.csv'));
plotWindowBefore = 2.0;
plotWindowAfter = 2.0;
ignoreInitialSeconds = 3.0;

if isempty(apfPath) || height(apfPath) == 0
    error('strategic_goal_path.csv is empty. Record /strategic_goal_path before exporting.');
end

selectedMsg = selectLocalApfMessage(apfPath, obstacles, ignoreInitialSeconds);
apfLocal = apfPath(apfPath.msg_index == selectedMsg, :);
apfTime = representativeTime(apfLocal, {'path_stamp', 'bag_time'});

eeHistory = selectLastOrAllPath(eePath);
eeLocal = selectTimeWindow(eeHistory, apfTime, plotWindowBefore, plotWindowAfter, ...
    {'point_stamp', 'bag_time'});
targetLocal = selectTimeWindow(targetState, apfTime, plotWindowBefore, plotWindowAfter, ...
    {'stamp', 'bag_time'});
predLocal = selectNearestPathMessage(targetPrediction, apfTime);
targetNearest = selectNearestTarget(targetState, apfTime);

if isempty(eeLocal) && ~isempty(eeHistory)
    warning('No end-effector samples found in the selected time window; plotting full latest path.');
    eeLocal = eeHistory;
end
if isempty(targetLocal) && ~isempty(targetState)
    warning('No target samples found in the selected time window; plotting full target trajectory.');
    targetLocal = targetState;
end

fprintf('Selected APF message %d at t=%.3f s; plotting target/EE window [%.3f, %.3f] s.\n', ...
    selectedMsg, apfTime, apfTime - plotWindowBefore, apfTime + plotWindowAfter);

figure('Name', 'APF local obstacle avoidance trajectory', 'Color', 'w');
hold on; grid on; axis equal;
set(gca, 'FontName', 'Times New Roman', 'FontSize', 11);

if ~isempty(eeLocal)
    plot(eeLocal.x, eeLocal.y, '-', 'Color', [0.10 0.35 0.90], 'LineWidth', 1.8, ...
        'DisplayName', 'End-effector trajectory near selected APF path');
end

if ~isempty(targetLocal)
    plot(targetLocal.x, targetLocal.y, '--', 'Color', [0.85 0.15 0.10], 'LineWidth', 1.4, ...
        'DisplayName', 'Estimated target trajectory near selected APF path');
end

if ~isempty(predLocal)
    plot(predLocal.x, predLocal.y, ':', 'Color', [0.95 0.45 0.05], 'LineWidth', 1.5, ...
        'DisplayName', 'EKF predicted target path');
end

plot(apfLocal.x, apfLocal.y, '-o', 'Color', [0.00 0.55 0.20], 'MarkerSize', 4, ...
    'LineWidth', 2.0, 'DisplayName', 'APF corrected local reference');

if ~isempty(targetNearest)
    plot([apfLocal.x(1), targetNearest.x], [apfLocal.y(1), targetNearest.y], '--', ...
        'Color', [0.45 0.45 0.45], 'LineWidth', 1.2, 'DisplayName', 'Direct reference without APF');
    scatter(targetNearest.x, targetNearest.y, 70, [0.90 0.10 0.10], 'filled', ...
        'DisplayName', 'Target near selected APF path');
end

plotObstacles(obstacles);

scatter(apfLocal.x(1), apfLocal.y(1), 60, [0.00 0.35 0.90], 'filled', ...
    'DisplayName', 'Selected local path start');
scatter(apfLocal.x(end), apfLocal.y(end), 70, [0.00 0.55 0.20], 'filled', ...
    'DisplayName', 'Selected local path end');

xlabel('X (m)');
ylabel('Y (m)');
title(sprintf('APF Local Obstacle Avoidance Reference, message %d', selectedMsg));
legend('Location', 'bestoutside');

padAxes(0.05);

outPng = fullfile(dataDir, 'apf_local_avoidance_xy.png');
outFig = fullfile(dataDir, 'apf_local_avoidance_xy.fig');
saveas(gcf, outPng);
savefig(gcf, outFig);
fprintf('Saved figure:\n  %s\n  %s\n', outPng, outFig);

%% Local helper functions
function T = readOptionalTable(path)
    if isfile(path)
        T = readtable(path, 'VariableNamingRule', 'preserve');
    else
        T = table();
    end
end

function msgIndex = selectLocalApfMessage(apfPath, obstacles, ignoreInitialSeconds)
    msgIds = unique(apfPath.msg_index);
    if isempty(msgIds)
        error('No APF path messages found.');
    end

    if nargin < 3
        ignoreInitialSeconds = 0.0;
    end

    if ignoreInitialSeconds > 0.0
        msgTimes = nan(numel(msgIds), 1);
        for i = 1:numel(msgIds)
            rows = apfPath(apfPath.msg_index == msgIds(i), :);
            msgTimes(i) = representativeTime(rows, {'path_stamp', 'bag_time'});
        end
        validTimes = msgTimes(isfinite(msgTimes));
        if ~isempty(validTimes)
            firstTime = min(validTimes);
            keep = isfinite(msgTimes) & msgTimes >= firstTime + ignoreInitialSeconds;
            if any(keep)
                msgIds = msgIds(keep);
            end
        end
    end

    if isempty(obstacles) || height(obstacles) == 0
        msgIndex = msgIds(max(1, round(numel(msgIds) / 2)));
        return;
    end

    bestDistance = inf;
    msgIndex = msgIds(1);
    for i = 1:numel(msgIds)
        local = apfPath(apfPath.msg_index == msgIds(i), :);
        for j = 1:height(obstacles)
            d = hypot(local.x - obstacles.x(j), local.y - obstacles.y(j));
            d = min(d);
            if d < bestDistance
                bestDistance = d;
                msgIndex = msgIds(i);
            end
        end
    end
end

function localPath = selectLastOrAllPath(pathTable)
    if isempty(pathTable) || height(pathTable) == 0
        localPath = table();
        return;
    end
    msgIds = unique(pathTable.msg_index);
    localPath = pathTable(pathTable.msg_index == msgIds(end), :);
end

function localRows = selectTimeWindow(dataTable, centerTime, beforeSeconds, afterSeconds, preferredTimeColumns)
    if isempty(dataTable) || height(dataTable) == 0 || ~isfinite(centerTime)
        localRows = table();
        return;
    end

    timeValues = tableTimeValues(dataTable, preferredTimeColumns);
    if isempty(timeValues) || ~any(isfinite(timeValues))
        localRows = table();
        return;
    end

    startTime = centerTime - beforeSeconds;
    endTime = centerTime + afterSeconds;
    mask = isfinite(timeValues) & timeValues >= startTime & timeValues <= endTime;
    localRows = dataTable(mask, :);
end

function centerTime = representativeTime(dataTable, preferredTimeColumns)
    centerTime = nan;
    if isempty(dataTable) || height(dataTable) == 0
        return;
    end

    timeValues = tableTimeValues(dataTable, preferredTimeColumns);
    validTimes = timeValues(isfinite(timeValues) & timeValues > 0.0);
    if ~isempty(validTimes)
        centerTime = median(validTimes, 'omitnan');
    end
end

function timeValues = tableTimeValues(dataTable, preferredTimeColumns)
    timeValues = nan(height(dataTable), 1);
    if isempty(dataTable) || height(dataTable) == 0
        return;
    end

    for i = 1:numel(preferredTimeColumns)
        columnName = preferredTimeColumns{i};
        if ismember(columnName, dataTable.Properties.VariableNames)
            candidate = dataTable.(columnName);
            if isnumeric(candidate) && any(isfinite(candidate) & candidate > 0.0)
                timeValues = candidate;
                return;
            end
        end
    end
end

function localPath = selectNearestPathMessage(pathTable, targetTime)
    if isempty(pathTable) || height(pathTable) == 0 || ~isfinite(targetTime)
        localPath = table();
        return;
    end
    msgIds = unique(pathTable.msg_index);
    msgTimes = zeros(numel(msgIds), 1);
    for i = 1:numel(msgIds)
        rows = pathTable(pathTable.msg_index == msgIds(i), :);
        msgTimes(i) = median(rows.bag_time, 'omitnan');
    end
    [~, idx] = min(abs(msgTimes - targetTime));
    localPath = pathTable(pathTable.msg_index == msgIds(idx), :);
end

function target = selectNearestTarget(targetTable, targetTime)
    if isempty(targetTable) || height(targetTable) == 0 || ~isfinite(targetTime)
        target = table();
        return;
    end
    targetTimes = tableTimeValues(targetTable, {'stamp', 'bag_time'});
    [~, idx] = min(abs(targetTimes - targetTime));
    target = targetTable(idx, :);
end

function plotObstacles(obstacles)
    if isempty(obstacles) || height(obstacles) == 0
        return;
    end

    for i = 1:height(obstacles)
        plotCircle(obstacles.x(i), obstacles.y(i), obstacles.radius(i), ...
            [0.45 0.45 0.45], 0.18, 'Obstacle radius');
        if ismember('influence_radius', obstacles.Properties.VariableNames) && ...
                isfinite(obstacles.influence_radius(i))
            plotCircle(obstacles.x(i), obstacles.y(i), obstacles.influence_radius(i), ...
                [0.45 0.45 0.45], 0.06, 'Obstacle influence range');
        end
        scatter(obstacles.x(i), obstacles.y(i), 50, [0.20 0.20 0.20], 'filled', ...
            'DisplayName', 'Obstacle center');
    end
end

function plotCircle(cx, cy, r, color, alphaValue, displayName)
    theta = linspace(0, 2 * pi, 160);
    x = cx + r * cos(theta);
    y = cy + r * sin(theta);
    patch(x, y, color, 'FaceAlpha', alphaValue, 'EdgeColor', color, ...
        'LineStyle', '--', 'DisplayName', displayName);
end

function padAxes(pad)
    xl = xlim;
    yl = ylim;
    dx = max(diff(xl), 1e-3);
    dy = max(diff(yl), 1e-3);
    xlim([xl(1) - pad * dx, xl(2) + pad * dx]);
    ylim([yl(1) - pad * dy, yl(2) + pad * dy]);
end
